package org.eclipse.jdt.internal.ui;

import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.ui.IDecoration;

public class InterfaceIndicatorLabelDecorator {

    public void addOverlays(Object element, IDecoration decoration) throws Exception {
        if (element instanceof ICompilationUnit) {
            System.out.println("Compilation unit: " + element);
        } else if (element instanceof IClassFile) {
            System.out.println("Class file: " + element);
        }
    }

    public static class JavaModelUtil {
        public static boolean isModuleInfo(ICompilationUnit unit) { return false; }
        public static boolean isModuleInfo(IClassFile file) { return false; }
        public static boolean is9OrHigher(org.eclipse.jdt.core.IJavaProject project) { return true; }
    }
}

